/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnspratosingredientesWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PRATINGRPRODCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &pratIngrProdCodigo1.FromString(&GridStateDynamicFilter.Value) If not &pratIngrProdCodigo1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Produto", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &pratIngrProdCodigo1 EndIf Case &DynamicFiltersSelector1 = !'AREENSETAPANOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome1.FromString(&GridStateDynamicFilter.Value) If not &AreEnsEtapaNome1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Etapa Nome ", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Etapa Nome ", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&AreEnsEtapaNome1) EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PRATINGRPRODCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &pratIngrProdCodigo2.FromString(&GridStateDynamicFilter.Value) If not &pratIngrProdCodigo2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Produto", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &pratIngrProdCodigo2 EndIf Case &DynamicFiltersSelector2 = !'AREENSETAPANOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome2.FromString(&GridStateDynamicFilter.Value) If not &AreEnsEtapaNome2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Etapa Nome ", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Etapa Nome ", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&AreEnsEtapaNome2) EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PRATINGRPRODCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &pratIngrProdCodigo3.FromString(&GridStateDynamicFilter.Value) If not &pratIngrProdCodigo3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Produto", "=") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &pratIngrProdCodigo3 EndIf Case &DynamicFiltersSelector3 = !'AREENSETAPANOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &AreEnsEtapaNome3.FromString(&GridStateDynamicFilter.Value) If not &AreEnsEtapaNome3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Etapa Nome ", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Etapa Nome ", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&AreEnsEtapaNome3) EndIf EndCase EndIf EndIf EndIf If not (&TFpratIngrProdCodigo_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Ingrediente") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = &TFpratIngrProdCodigo_SelDsc
Else If not (&TFpratIngrProdCodigo.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Ingrediente") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFpratIngrProdCodigo) EndIf EndIf If not (&TFAreEnsEtapaNome_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Etapa") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFAreEnsEtapaNome_Sel) Else If not (&TFAreEnsEtapaNome.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Etapa") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFAreEnsEtapaNome) EndIf EndIf If not (&TFcarGruTurno_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Turno") &i = 1 For &TFcarGruTurno_Sel in &TFcarGruTurno_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += &TFcarGruTurno_Sel.EnumerationDescription() &i += 1 EndFor EndIf If not (&TFpratIngrQuantidade.IsEmpty() AND &TFpratIngrQuantidade_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Qtdade (percapta)") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFpratIngrQuantidade WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFpratIngrQuantidade_To EndIf If not (&TFpratIngrStatus_Sels.Count = 0) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Situação") &i = 1 For &TFpratIngrStatus_Sel in &TFpratIngrStatus_Sels If &i = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = '' Else &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += ', ' EndIf &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text += &TFpratIngrStatus_Sel.EnumerationDescription() &i += 1 EndFor EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnspratosingredientesWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnspratosingredientesWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnspratosingredientes order prefCodigo pratoCodigo AreEnsSequencial pratIngrProdCodigo when &OrderedBy = 1 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (pratIngrProdCodigo) when &OrderedBy = 1 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial AreEnsEtapaNome when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (AreEnsEtapaNome) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial carGruTurno when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (carGruTurno) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial pratIngrQuantidade when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (pratIngrQuantidade) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo pratoCodigo AreEnsSequencial pratIngrStatus when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (pratoCodigo) (AreEnsSequencial) (pratIngrStatus) when &OrderedBy = 5 AND &OrderedDsc = True
using trnspratosingredientesWWDS(&prefCodigo, &pratoCodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &pratIngrProdCodigo1, &AreEnsEtapaNome1 , &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &pratIngrProdCodigo2, &AreEnsEtapaNome2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &pratIngrProdCodigo3, &AreEnsEtapaNome3, &TFpratIngrProdCodigo, &TFpratIngrProdCodigo_Sel , &TFAreEnsEtapaNome, &TFAreEnsEtapaNome_Sel, &TFcarGruTurno_Sels, &TFpratIngrQuantidade, &TFpratIngrQuantidade_To, &TFpratIngrStatus_Sels) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'pratIngrProdCodigo' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(prodDescricao) Case &ColumnsSelector_Column.ColumnName = !'AreEnsEtapaNome' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(AreEnsEtapaNome) Case &ColumnsSelector_Column.ColumnName = !'carGruTurno' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = carGruTurno.EnumerationDescription() Case &ColumnsSelector_Column.ColumnName = !'pratIngrQuantidade' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = pratIngrQuantidade Case &ColumnsSelector_Column.ColumnName = !'pratIngrStatus' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = pratIngrStatus.EnumerationDescription() EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnspratosingredientesWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"pratIngrProdCodigo", '', !'Ingrediente', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"AreEnsEtapaNome", '', !'Etapa', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"carGruTurno", '', !'Turno', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"pratIngrQuantidade", '', !'Qtdade (percapta)', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"pratIngrStatus", '', !'Situação', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnspratosingredientesWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnspratosingredientesWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnspratosingredientesWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnspratosingredientesWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPRATINGRPRODCODIGO" &TFpratIngrProdCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRATINGRPRODCODIGO_SEL" &TFpratIngrProdCodigo_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSETAPANOME" &TFAreEnsEtapaNome.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFAREENSETAPANOME_SEL" &TFAreEnsEtapaNome_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARGRUTURNO_SEL" &TFcarGruTurno_SelsJson = &GridStateFilterValue.Value &TFcarGruTurno_Sels.FromJson(&TFcarGruTurno_SelsJson) Case &GridStateFilterValue.Name = !"TFPRATINGRQUANTIDADE" &TFpratIngrQuantidade.FromString(&GridStateFilterValue.Value) &TFpratIngrQuantidade_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRATINGRSTATUS_SEL" &TFpratIngrStatus_SelsJson = &GridStateFilterValue.Value &TFpratIngrStatus_Sels.FromJson(&TFpratIngrStatus_SelsJson) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&PRATOCODIGO" &pratoCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
